```python
def is_prime(n):
    """Check if a given number is prime using a while loop."""
    if n < 2:
        return False

    # Check for divisibility up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False

    return True

# Get user input
user_input = int(input("Enter a number to check if it's prime: "))

# Check if the number is prime
if is_prime(user_input):
    print(f"{user_input} is prime.")
else:
    print(f"{user_input} is not prime.")
```

